using InovaGed.Application.Continuity; using Microsoft.Extensions.Configuration;
namespace InovaGed.Infrastructure.Continuity;
public sealed class RestoreValidationService(IConfiguration cfg):IRestoreValidationService { public Task<RestoreValidationResult> ValidateTargetAsync(string host,string database,bool confirmed,string justification,CancellationToken ct){var raw=cfg.GetConnectionString("DefaultConnection")??string.Empty;var prod=string.IsNullOrWhiteSpace(raw)?null:new Npgsql.NpgsqlConnectionStringBuilder(raw);var allow=cfg.GetSection("RestoreTest:AllowedDatabases").Get<string[]>()??[];if(!confirmed||string.IsNullOrWhiteSpace(justification))return Task.FromResult(new RestoreValidationResult(false,"Confirmação e justificativa são obrigatórias."));if(prod is not null&&string.Equals(prod.Host,host,StringComparison.OrdinalIgnoreCase)&&string.Equals(prod.Database,database,StringComparison.OrdinalIgnoreCase))return Task.FromResult(new RestoreValidationResult(false,"Destino de produção bloqueado."));return Task.FromResult(allow.Contains(database,StringComparer.OrdinalIgnoreCase)?new RestoreValidationResult(true,"Destino isolado autorizado."):new RestoreValidationResult(false,"Destino fora da allowlist."));} }
